) AS (
  VALUES 
    (89::BIGINT, 'Muy facil el curso en veranpo, todo se hace en grupo. La mirtad del curso lo da el la otra Chine, es muy facil por ambas partes. Con el libro se pasa sin necesidad de ir a clases'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, '406f3f41f92d680eb80a7de771bd74f59bad3042ef6806ee2d5b497aaff79e5b'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Adrián es excelente para cualquier curso de mecánica. Realmente sabe del tema y sus explicaciones son muy buenas, eso sí, el curso es muy difícil, el profe ayuda en lo que puede, pero hay que estudiar bastante, le recomiendo ir a clases.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '43e7f4991f9dc2994415a51ce79d1723712e5ccaf527c15c67835b5a08c0b0ba'::TEXT, ARRAY[2754]::BIGINT[]),
    (89::BIGINT, 'Es el profesor de Fluidos Sabe mucho de la materia, explica muy claro y pregunta constantemente si uno está entendiendo. Deja muchas tareas para entender el tema y hace exámenes para la casa. En el curso se aprende a usar muchos programas para resolver problemas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '13dcb3b48d363dd0d71cc6c09d233c43c38982ce84ed2cd42d59d13df527370a'::TEXT, ARRAY[2750]::BIGINT[]),
    (89::BIGINT, 'El profe da buenas explicaciones y no califica muy duro (al menos en verano hacía tareas y exámenes bastante sencillos).'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'ce3e01816c1b5408ed2e986c03107e59eae10551031dd6c4764f011309da6b41'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Muy buen profesor. Es bastante claro en lo que enseña y los examenes no son muy dificiles. El curso de por sí es sencillo, el lo hace 3 veces más. Es demasiado ordenado y deja todas las asignaciones (tareas programadas, examenes, tareas, quices) establecidos desde el principio del semestre.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '4622aba3497ddddb1dcdd7cf0a6e786d4efa6c4dc41213b7f09e3540add65ee5'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Sus explicaciones son excelentes. El curso en sí es complicado, pero el intenta que todos entiendan, deja muchas tareas para practicar. Le gusta que sepamos un poco de todo, por lo que deja simulaciones en pipe flow, comsol y programaciones en matlab o excel.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a16ecc126709f8dc4a420e8d11bcf2239f6cca9dd14bc1f186ad49b80ebd42d5'::TEXT, ARRAY[2750]::BIGINT[]),
    (89::BIGINT, 'Evalúa justo y explica bien. Al inicio el curso es un toque duro pero se va a haciendo fácil hacia el final'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'dc59f86d3a72cb4eec9b8d5e51e3338a17be1bdd076fd033a96d5d3f8e406872'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Explica muy bien, va al grano y se entiende todo perfecto. Es muy amable al responder consultas y siempre atento a ayudar. Califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, '9ce9cd651fafb4fde7f10da6e9f9e80040c45a5329540a53d5b4bc55c232de80'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Es un profesor excelente!! Posee un amplio dominio de la materia y sabe explicar muy bien (en forma simple de entender)!!! Hace bastante práctica en clase, y sirve mucho para los exámenes y tareas. Para dudas, es muy pendiente de responderlas de la mejor manera. Súper recomendado!! 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'a8c4f327835a7de787a58c1cd35014b37426e2a41226074f9f887bc8b1feea75'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Si quiere aprender, hay que llevar el curso en otro lado'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-07-21T00:00:00+00:00'::TIMESTAMPTZ, '8548beb189ee98cd023c74f41bc2879e560592a82d09eba95bc5510816db6ba8'::TEXT, ARRAY[2754]::BIGINT[]),
    (89::BIGINT, 'Los trabajos son largos, pero el mucha paciencia para explicar y trata de ayudar al estudiante .'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '02807f50537c781b21cfca0d00add70f9c78457c7c4f94175fc07b19da3823ad'::TEXT, ARRAY[610]::BIGINT[]),
    (89::BIGINT, 'El curso en sí es muy fácil, solo hay que tener el cuidado que él deja todo los trabajos del curso desde el principio del semestre y después se olvida de acordar o avisar de estos. Aprenda a manejar Matlab si o si, ya que aunque no se vea mucho en clase, siempre hay que usarlo para los examenes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'f98ee4174be1e0180922db9d383a6d886df92ca16dcd0c5885a746f87a8ea60e'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Excelente profe, muy comprensivo y ordenado para dar las clases, super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1d79fa2d55c580df820a6e1b3c7436a99bf586298eb11dc4fcb5744c89a74792'::TEXT, ARRAY[2754]::BIGINT[]),
    (89::BIGINT, 'En términos generales es un buen profe. Explica los métodos de forma que sean fáciles de entender y aplicar. Durante las clases le va dando todo lo que necesita usar para tareas y exámenes, y a veces tarda en calificar, pero lo hace suavemente. Bastante recomendado. PD: consiga MATLAB a como pueda'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'a48fa6c1ff10e9606381be98002b866454d0caa38ffe9fafb09009750922d6c8'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Super buen profe, es muy claro con la materia, las tareas y examenes van al punto, se aprende a aplicar los métodos de manera ágil y simple, lo que se necesita!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-09-12T00:00:00+00:00'::TIMESTAMPTZ, '4322b2622d50ee06e40d4610c87666963bc7db04015974a6caa7ebd6d675b7ce'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Deja muchos trabajos, explica las cosas claras pero no tiene un conocimiento muy profundo de los temas. Si lo agarra a uno entre ojos ya perdió el curso, mejor llevarse bien con él.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '70dc41f738c979228b41c3b7c05577baf5ab2770a3b714ee74e5ed5e68025c90'::TEXT, ARRAY[2750]::BIGINT[]),
    (89::BIGINT, 'Super organizado, muy claro, exámenes fáciles, solo de poner atención. Deja muchas tareas, pero se hacen en un par de horas y son en parejas. El mejor profe que he tenido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '696de2fa0060d998f6dd80386f489fb599f86ee9a446dc6dac39588a2bbd1c5a'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '58eafccc969283592f2da7b9e39ecb7aad008f7f1f1ae6dfd7c063b67f931695'::TEXT, ARRAY[2749, 2748]::BIGINT[]),
    (89::BIGINT, 'Explica regular, clases aburridas, califica duro. En verano comparte el curso con Bruno Chine'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, '3f1843a2f82d6c815f5a4edbb40a062ee8bc40553f816e3905e390115e1ee18d'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Deja bastantes tareas, pero son fáciles. Ayuda un montón si ve que le pone, es bastante flexible con algunas cosas. Quices fáciles. Lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4d29a68a51e0e80af60246d7409637906e8053e016f7c588944bc30ad5cdc5b8'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '75f43ba842a21d0dddc0bb0b87ecbb82b2d194b3b6a686233c18ce43a37d0ad4'::TEXT, ARRAY[2754]::BIGINT[]),
    (89::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '56154e0858316733690eed45bd85fad88d4d2f59f24879e49e68d230d7e8fc26'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Explica muy bien, ayuda bastante en las evaluaciones y califica justamente. Deja bastantes trabajos y prácticas pero al final es una buena opción como profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ce3a89902bf28570be6ada6f923941602b2bf3ac503a5f43e978e6bd194b6010'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Es bueno, califica durillo pero justo. La materia que enseña es lo que sale en el examen no se vuela con nada rudo. Eso sí, deja muchas tareas y las programadas si bien son fáciles son largas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, '4f028afff8d0e17c3b7db53cb4cb0d4de37af9aa56e265c28c591c07b679edaa'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Si él ve que usted va a clase a poner atención y le pone, le ayuda, de lo contrario no. Explica bien, sin embargo hay que practicar bastante, las tareas programadas si quitan tiempo, pero aprende un montón.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '983d4dc08d60b4b4c117060299e7b1f9addb82965a6b85314ff4c15a91262673'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Se aprende demasiado con este profe!! Si lo que busca es pasar el curso sin hacer nada, mejor busque otro profe que más se adecúe a tus necesidades,porque el profe deja tareas, prácticas, tareas programadas y hace 6 quices a petición del grupo. Si le pone ganas a esto, los exámenes no son difíciles'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'df8575fedfe9777fb3c9509d7f11a5f3e992bcb110fc008aee4fa8d05f24a0f8'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Es regular explicando, a veces es mejor guiarse con el libro. En los exámenes califica binario y da poco tiempo. Es importante llevar la materia al día.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '0d0ead5d9f7b991cf461dd12634196220051fee153a07ea3b1856d8e03e9ebc6'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'El mae no sabe como explicar bien la materia, sin embargo sabe bastante. En consulta logra ser un poco más claro y explica las veces necesarias. Si uno le pone le ayuda.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '5d87979ba1eaf7660efc02e623e4575f2df9e921d52e893390a660e35369170e'::TEXT, ARRAY[949]::BIGINT[]),
    (89::BIGINT, 'El mae califica duro, póngale en los quices porque valen un 20% de la nota, ponga atención en clases porque son sumamente aburridas, si no se se va en el viaje se aburre.. Es una opción'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'aee229c1e6a8d0588b811f358a14aaf615bec823b0b1e5d6051a4aa1716ecc4b'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Explica todo muy rápido en presentaciones, las cuales no sube. Los exámenes los hace muy duros, con problemas para nada parecidos a los vistos en clase o a los que manda de práctica. No devuelve el enunciado del examen, por lo que es imposible reclamarle algo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '2be6eadfbaea0c3bd4397b5e9cb69ea73f923e9eb9688bc3b29857145ed6bef2'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'El mae no sabe como explicar la materia en si. Prácticamente no va entender nada de la explicación. Hace los quices muy difíciles y también los exámenes.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Exámenes retadores']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '2180150051a010d2f92c330889ba40cb63921c8e467bb3e8e063b3b4ee9cefba'::TEXT, ARRAY[949]::BIGINT[]),
    (89::BIGINT, 'Imae... Rudillo, la verdad, pero se ve que quiere ayudar a los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'c6f84adf539c7c5afccee4950bb5b85d14c6e1c05d869b067eb4eea373261dc4'::TEXT, ARRAY[949]::BIGINT[]),
    (89::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2018-03-14T00:00:00+00:00'::TIMESTAMPTZ, '9219eaa0e09842e52663990a126f6eb143ee2b835ab2b8e5f3ecd6d1f751df94'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Es un profe muy tranquilo. Explica con presentaciones y el curso es muy aburrido. Lo que más atrasa son las tareas (normales) que deja fuera de clase. Hace cuices muy seguidos y los exámenes son sencillos. El curso es muy metódico.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '0bd33bf83edcabf5c5162ce41dec8e9a2ac3902328e0d72377c5129a9e4a484a'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'En verano el curso se pasa súper fácil, por lo general el profe no hace exámenes (sólo quices de la materia del día anterior todos los días y deja como 2 tareas para la casa). Se sale antes y la materia la explica bien, los quices son bastante similares a los ejemplos vistos en clases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '4f4655d896e523a92949a45e5d07d80877406f645eb415af4df1b1a683249bea'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Explica bien, en sí el curso es bastante aburrido y tedioso, por lo menos él deja salir antes. Las progras no son del otro mundo pero tampoco se hacen tan rápido. El primer examen es el más duro, pero el curso es pasable.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '58e7dde93da92b05f25d6273fc8caa85f63a0464295fd98dc371e7191c9af95e'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Como profe no es la gran cosa, siempre se sale mucho antes. Los quices son sumamente fáciles y las tareas son largas, si se consiguen las progras el curso se vuelve sencillo. Los exámenes son un poco dificiles pero califica suave'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '39cad3a8f53edd70e0b0b0b4a88358fe8e0ac26d3b76e7989d7fe7d3b6ac0ab1'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-10-13T00:00:00+00:00'::TIMESTAMPTZ, 'e987573ef495d46a3b4194ea328a6b470f8917d43f651dcefe3b1a9233434463'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0d8f41b7a0c28bb8cbc712d8e2bced25422bfda66775b13f09ec4bcca274f3ed'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Se pasa pero no es la gran cosa, es algo argollero. Las programadas son las mismas todos los semestres, si las consigue es una salvada.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ce9036c9eb3bd15eb8eb4ff1d657e4bc4264e2801167c6ca916b6862ed45a9a9'::TEXT, ARRAY[968]::BIGINT[]),
    (89::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-26T00:00:00+00:00'::TIMESTAMPTZ, 'c79881dff58501565148a904fb150d0e5545c97f88d9294a4b3d511dfaa2d94e'::TEXT, ARRAY[968]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
